from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Any, AsyncIterator, Literal, Optional

from g4f import debug
from g4f.providers.response import JsonConversation, Reasoning


DEEPSEEK_MESSAGE_STATUSES = {
    "FINISHED",
    "CONTENT_FILTER",
    "CONTEXT_LENGTH_EXCEEDED",
    "INCOMPLETE",
    "WIP",
    "TIMEOUT",
}
DEEPSEEK_FINISH_REASONS = {
    "FINISHED": "stop",
    "CONTENT_FILTER": "content_filter",
    "CONTEXT_LENGTH_EXCEEDED": "length",
    "INCOMPLETE": "incomplete",
    "WIP": "wip",
    "TIMEOUT": "timeout",
}

DEEPSEEK_RESPONSE_FRAGMENT_TYPES = {"RESPONSE", "TEMPLATE_RESPONSE"}
DEEPSEEK_REASONING_FRAGMENT_TYPES = {
    "THINK",
    "THINKING",
    "REASONING",
    "SEARCH",
    "TOOL_SEARCH",
    "TOOL_OPEN",
    "TOOL_FIND",
}
DEEPSEEK_METADATA_FRAGMENT_TYPES = {
    "REQUEST",
    "FILE",
    "TIP",
    "READ_LINK",
}


async def iter_deepseek_sse(response) -> AsyncIterator[tuple[str, Any]]:
    """Parse DeepSeek SSE frames without losing their ``event`` field."""
    event_type = "message"
    data_lines: list[str] = []

    def decode_event() -> Optional[tuple[str, Any]]:
        if not data_lines:
            return None
        raw_data = "\n".join(data_lines)
        if raw_data.strip() == "[DONE]":
            return None
        try:
            return event_type, json.loads(raw_data)
        except json.JSONDecodeError as error:
            raise ValueError(
                f"Invalid DeepSeek SSE JSON data: {raw_data!r}"
            ) from error

    async for raw_line in response.iter_lines():
        line = (
            raw_line.decode("utf-8")
            if isinstance(raw_line, (bytes, bytearray))
            else str(raw_line)
        ).rstrip("\r")

        if not line:
            event = decode_event()
            if event is not None:
                yield event
            event_type = "message"
            data_lines = []
            continue

        if line.startswith(":"):
            continue

        field_name, separator, field_value = line.partition(":")
        if not separator:
            continue
        if field_value.startswith(" "):
            field_value = field_value[1:]
        if field_name == "event":
            event_type = field_value or "message"
        elif field_name == "data":
            data_lines.append(field_value)

    event = decode_event()
    if event is not None:
        yield event


@dataclass
class _DeepSeekStreamState:
    message_id: Any = None
    status: Optional[str] = None
    closed: bool = False
    active_kind: Optional[str] = "response"
    fragment_kinds: dict[str, Optional[str]] = field(default_factory=dict)
    next_fragment_index: int = 0
    emitted: dict[str, str] = field(
        default_factory=lambda: {"reasoning": "", "response": ""}
    )

    def append(self, kind: str, content: str) -> str:
        self.emitted[kind] += content
        return content

    def snapshot_delta(self, kind: str, content: str) -> str:
        """Return only text not already emitted by an earlier stream attempt."""
        previous = self.emitted[kind]
        if content.startswith(previous):
            delta = content[len(previous):]
            self.emitted[kind] = content
            return delta
        if previous.startswith(content):
            return ""

        max_overlap = min(len(previous), len(content))
        for overlap in range(max_overlap, 0, -1):
            if previous.endswith(content[:overlap]):
                delta = content[overlap:]
                self.emitted[kind] += delta
                return delta

        self.emitted[kind] += content
        return content


def _fragment_kind(fragment: dict) -> Optional[str]:
    fragment_type = str(fragment.get("type", "")).upper()
    if not fragment_type:
        return "response"
    if fragment_type in DEEPSEEK_RESPONSE_FRAGMENT_TYPES:
        return "response"
    if fragment_type in DEEPSEEK_REASONING_FRAGMENT_TYPES:
        return "reasoning"
    return None


def _stream_output(kind: str, content: str):
    if not content:
        return None
    return Reasoning(content) if kind == "reasoning" else content


def _record_fragment_kind(
        state: _DeepSeekStreamState,
        fragment_index: str,
        kind: Optional[str],
        *,
        append_fragment: bool = False,
) -> None:
    state.active_kind = kind
    debug.log(
        "DeepSeekAuth: Stream fragment: "
        f"index={_stream_log_value(fragment_index)} "
        f"kind={_stream_log_value(kind)} "
        f"append={_stream_log_value(append_fragment)}"
    )

    if fragment_index == "-1":
        state.fragment_kinds["-1"] = kind
        if append_fragment:
            state.fragment_kinds[str(state.next_fragment_index)] = kind
            state.next_fragment_index += 1
        elif state.next_fragment_index:
            state.fragment_kinds[str(state.next_fragment_index - 1)] = kind
        return

    state.fragment_kinds[fragment_index] = kind
    try:
        numeric_index = int(fragment_index)
    except ValueError:
        return
    if numeric_index >= state.next_fragment_index:
        state.next_fragment_index = numeric_index + 1
    if numeric_index == state.next_fragment_index - 1:
        state.fragment_kinds["-1"] = kind


def _fragment_index_from_path(path: str) -> Optional[str]:
    path_parts = path.split("/")
    if (
            len(path_parts) >= 3
            and path_parts[0] == "response"
            and path_parts[1] == "fragments"
    ):
        return path_parts[2]
    return None


def _record_response_message_id(
        state: _DeepSeekStreamState,
        conversation: JsonConversation,
        message_id: Any,
) -> None:
    if message_id is not None:
        state.message_id = message_id
        conversation.parent_message_id = message_id


def _record_stream_status(
        state: _DeepSeekStreamState,
        path: str,
        value: Any,
        *,
        operation: Optional[str] = None,
        source: Literal["patch", "snapshot"] = "snapshot",
) -> bool:
    if path not in {"response/status", "quasi_status", "response/quasi_status"}:
        return False
    status = str(value).upper()
    if status in DEEPSEEK_MESSAGE_STATUSES:
        state.status = status
        interpretation = "requires_continue" if status == "INCOMPLETE" else None
        operation_label = operation if operation is not None else "none"
        message = (
            "DeepSeekAuth: Stream status: "
            f"status={status} source={source} operation={operation_label}"
        )
        if interpretation is not None:
            message += f" interpretation={interpretation}"
        debug.log(message)
    return True


def _stream_log_value(value: Any) -> str:
    """Format a small, non-content stream field for diagnostic logging."""
    if value is None:
        return "none"
    if isinstance(value, bool):
        return str(value).lower()
    if isinstance(value, (int, float)):
        return str(value)
    if isinstance(value, str):
        sanitized = "".join(
            character
            if character.isalnum() or character in {"_", "-", "."}
            else "_"
            for character in value[:64]
        )
        return sanitized or "empty"
    return type(value).__name__


def _process_fragments(
        fragments: list,
        state: _DeepSeekStreamState,
        *,
        snapshot: bool,
) -> list:
    chunks = []
    content_by_kind = {"reasoning": "", "response": ""}
    kind_order = []

    if snapshot:
        state.fragment_kinds.clear()
        state.next_fragment_index = 0

    for fragment in fragments:
        if not isinstance(fragment, dict):
            continue
        kind = _fragment_kind(fragment)
        fragment_index = str(state.next_fragment_index)
        _record_fragment_kind(state, fragment_index, kind)
        content = fragment.get("content")
        if kind is None or not isinstance(content, str):
            continue

        if snapshot:
            if kind not in kind_order:
                kind_order.append(kind)
            content_by_kind[kind] += content
            continue

        output = _stream_output(kind, state.append(kind, content))
        if output is not None:
            chunks.append(output)

    if snapshot:
        for kind in kind_order:
            output = _stream_output(
                kind,
                state.snapshot_delta(kind, content_by_kind[kind]),
            )
            if output is not None:
                chunks.append(output)
    return chunks


def _process_stream_payload(
        payload: Any,
        state: _DeepSeekStreamState,
        conversation: JsonConversation,
) -> list:
    """Apply one DeepSeek message event and return newly visible output chunks."""
    if not isinstance(payload, dict):
        return []

    chunks = []
    _record_response_message_id(
        state, conversation, payload.get("response_message_id")
    )

    operation = payload.get("o")
    value = payload.get("v")
    if operation == "BATCH" and isinstance(value, list):
        for batch_item in value:
            chunks.extend(_process_stream_payload(batch_item, state, conversation))
        return chunks

    if isinstance(value, dict) and isinstance(value.get("response"), dict):
        response_obj = value["response"]
        _record_response_message_id(
            state, conversation, response_obj.get("message_id")
        )
        response_status = response_obj.get("status")
        if response_status is not None:
            _record_stream_status(
                state,
                "response/status",
                response_status,
                source="snapshot",
            )

        fragments = response_obj.get("fragments", [])
        if isinstance(fragments, list):
            chunks.extend(_process_fragments(fragments, state, snapshot=True))
        return chunks

    path = payload.get("p")
    if (
            path == "response/fragments"
            and operation in {"SET", "APPEND"}
            and isinstance(value, list)
    ):
        chunks.extend(
            _process_fragments(value, state, snapshot=operation == "SET")
        )
        return chunks

    fragment_index = (
        _fragment_index_from_path(path)
        if isinstance(path, str)
        else None
    )
    if (
            fragment_index is not None
            and path.count("/") == 2
            and operation in {"SET", "APPEND"}
            and isinstance(value, dict)
    ):
        kind = _fragment_kind(value)
        _record_fragment_kind(
            state,
            fragment_index,
            kind,
            append_fragment=operation == "APPEND",
        )
        content = value.get("content")
        if kind is not None and isinstance(content, str):
            delta = (
                state.snapshot_delta(kind, content)
                if operation == "SET"
                else state.append(kind, content)
            )
            output = _stream_output(kind, delta)
            if output is not None:
                chunks.append(output)
        return chunks

    if isinstance(path, str) and "v" in payload:
        if _record_stream_status(
                state,
                path,
                value,
                operation=operation,
                source="patch",
        ):
            return chunks
        if (
                fragment_index is not None
                and path.endswith("/type")
                and isinstance(value, str)
        ):
            _record_fragment_kind(
                state,
                fragment_index,
                _fragment_kind({"type": value}),
            )
            return chunks
        if path.endswith("/content") and isinstance(value, str):
            kind = (
                state.fragment_kinds[fragment_index]
                if fragment_index in state.fragment_kinds
                else state.active_kind
            )
            if kind is None:
                return chunks
            content = (
                state.snapshot_delta(kind, value)
                if operation == "SET"
                else state.append(kind, value)
            )
            output = _stream_output(kind, content)
            if output is not None:
                chunks.append(output)
        return chunks

    if isinstance(value, str):
        kind = state.active_kind
        if kind is None:
            return chunks
        output = _stream_output(kind, state.append(kind, value))
        if output is not None:
            chunks.append(output)
    return chunks


def _process_full_message(
        biz_data: Any,
        state: _DeepSeekStreamState,
        conversation: JsonConversation,
) -> list:
    """Convert a non-SSE full-message response into normal provider chunks."""
    if not isinstance(biz_data, dict):
        raise RuntimeError("DeepSeek resume returned an invalid full message")

    response = biz_data.get("response")
    if not isinstance(response, dict):
        response = biz_data.get("response_message") or biz_data.get("message")
    if not isinstance(response, dict) and "fragments" in biz_data:
        response = biz_data
    if not isinstance(response, dict):
        raise RuntimeError("DeepSeek resume returned an invalid full message")

    return _process_stream_payload(
        {"v": {"response": response}},
        state,
        conversation,
    )

// Package openai implements thinking configuration for OpenAI/Codex models.
//
// OpenAI models use the reasoning_effort format with discrete levels
// (low/medium/high). Some models support xhigh and none levels.
// See: _bmad-output/planning-artifacts/architecture.md#Epic-8
package openai

import (
	"github.com/router-for-me/CLIProxyAPI/v7/internal/registry"
	"github.com/router-for-me/CLIProxyAPI/v7/internal/thinking"
	"github.com/tidwall/gjson"
	"github.com/tidwall/sjson"
)

// Applier implements thinking.ProviderApplier for OpenAI models.
//
// OpenAI-specific behavior:
//   - Output format: reasoning_effort (string: low/medium/high/xhigh)
//   - Level-only mode: no numeric budget support
//   - Some models support ZeroAllowed (gpt-5.1, gpt-5.2)
type Applier struct{}

var _ thinking.ProviderApplier = (*Applier)(nil)

// NewApplier creates a new OpenAI thinking applier.
func NewApplier() *Applier {
	return &Applier{}
}

func init() {
	thinking.RegisterProvider("openai", NewApplier())
}

// Apply applies thinking configuration to OpenAI request body.
//
// Expected output format:
//
//	{
//	  "reasoning_effort": "high"
//	}
func (a *Applier) Apply(body []byte, config thinking.ThinkingConfig, modelInfo *registry.ModelInfo) ([]byte, error) {
	if thinking.IsUserDefinedModel(modelInfo) {
		return applyCompatibleOpenAI(body, config)
	}
	if modelInfo.Thinking == nil {
		return body, nil
	}

	// Only handle ModeLevel and ModeNone; other modes pass through unchanged.
	if config.Mode != thinking.ModeLevel && config.Mode != thinking.ModeNone {
		return body, nil
	}

	if len(body) == 0 || !gjson.ValidBytes(body) {
		body = []byte(`{}`)
	}

	if config.Mode == thinking.ModeLevel {
		result, _ := sjson.SetBytes(body, "reasoning_effort", string(config.Level))
		return result, nil
	}

	effort := ""
	support := modelInfo.Thinking
	if config.Budget == 0 {
		if support.ZeroAllowed || thinking.HasLevel(support.Levels, string(thinking.LevelNone)) {
			effort = string(thinking.LevelNone)
		}
	}
	if effort == "" && config.Level != "" {
		effort = string(config.Level)
	}
	if effort == "" && len(support.Levels) > 0 {
		effort = support.Levels[0]
	}
	if effort == "" {
		return body, nil
	}

	result, _ := sjson.SetBytes(body, "reasoning_effort", effort)
	return result, nil
}

func applyCompatibleOpenAI(body []byte, config thinking.ThinkingConfig) ([]byte, error) {
	if len(body) == 0 || !gjson.ValidBytes(body) {
		body = []byte(`{}`)
	}

	var effort string
	switch config.Mode {
	case thinking.ModeLevel:
		if config.Level == "" {
			return body, nil
		}
		effort = string(config.Level)
	case thinking.ModeNone:
		effort = string(thinking.LevelNone)
		if config.Level != "" {
			effort = string(config.Level)
		}
	case thinking.ModeAuto:
		// Auto mode for user-defined models: pass through as "auto"
		effort = string(thinking.LevelAuto)
	case thinking.ModeBudget:
		// Budget mode: convert budget to level using threshold mapping
		level, ok := thinking.ConvertBudgetToLevel(config.Budget)
		if !ok {
			return body, nil
		}
		effort = level
	default:
		return body, nil
	}

	result, _ := sjson.SetBytes(body, "reasoning_effort", effort)
	return result, nil
}

package handlers

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
)

type openAIResponsesStreamErrorChunk struct {
	Type           string         `json:"type"`
	Error          map[string]any `json:"error"`
	SequenceNumber int            `json:"sequence_number"`
}

type openAIResponsesStreamFailedChunk struct {
	Type           string                              `json:"type"`
	SequenceNumber int                                 `json:"sequence_number"`
	Response       openAIResponsesStreamFailedResponse `json:"response"`
}

type openAIResponsesStreamFailedResponse struct {
	Status string         `json:"status"`
	Error  map[string]any `json:"error"`
}

// openAIResponsesStreamErrorClass pairs the OpenAI error code and the OpenAI
// error type that a given HTTP status is reported as.
//
// The two are kept together deliberately. They are halves of one classification
// and a client reads both: the code names the condition, the type says whose
// fault it was and therefore whether a retry is allowed. Deriving them in two
// places let them contradict each other, which is how a Codex stream that was
// cut in transit came to be reported with the retryable code "request_timeout"
// alongside the type "invalid_request_error" — a type that tells every
// downstream consumer the request was malformed and must not be replayed.
type openAIResponsesStreamErrorClass struct {
	code      string
	errorType string
}

const (
	openAIResponsesClientErrorType = "invalid_request_error"
	openAIResponsesServerErrorType = "server_error"
)

// openAIResponsesStreamErrorClasses holds the statuses that do not follow the
// plain "4xx is the caller's fault, 5xx is ours" split.
//
// StatusRequestTimeout is the reason this table exists. A Codex stream that ends
// before response.completed is surfaced with that status, and the request itself
// was well formed: the connection failed, so the caller may replay it.
var openAIResponsesStreamErrorClasses = map[int]openAIResponsesStreamErrorClass{
	http.StatusUnauthorized:    {code: "invalid_api_key", errorType: openAIResponsesClientErrorType},
	http.StatusForbidden:       {code: "insufficient_quota", errorType: openAIResponsesClientErrorType},
	http.StatusTooManyRequests: {code: "rate_limit_exceeded", errorType: openAIResponsesClientErrorType},
	http.StatusNotFound:        {code: "model_not_found", errorType: openAIResponsesClientErrorType},
	http.StatusRequestTimeout:  {code: "request_timeout", errorType: openAIResponsesServerErrorType},
}

func openAIResponsesStreamErrorClassFor(status int) openAIResponsesStreamErrorClass {
	if class, ok := openAIResponsesStreamErrorClasses[status]; ok {
		return class
	}
	if status >= http.StatusInternalServerError {
		return openAIResponsesStreamErrorClass{code: "internal_server_error", errorType: openAIResponsesServerErrorType}
	}
	if status >= http.StatusBadRequest {
		return openAIResponsesStreamErrorClass{code: "invalid_request_error", errorType: openAIResponsesClientErrorType}
	}
	return openAIResponsesStreamErrorClass{code: "unknown_error", errorType: openAIResponsesClientErrorType}
}

func openAIResponsesStreamErrorCode(status int) string {
	return openAIResponsesStreamErrorClassFor(status).code
}

func openAIResponsesStreamErrorType(status int) string {
	return openAIResponsesStreamErrorClassFor(status).errorType
}

func unmarshalJSONWithNumber(data []byte, v any) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	return dec.Decode(v)
}

// BuildOpenAIResponsesStreamErrorChunk builds an OpenAI Responses streaming error chunk.
// It matches the official responses streaming event shape where the error details are nested.
func BuildOpenAIResponsesStreamErrorChunk(status int, errText string, sequenceNumber int) []byte {
	if status <= 0 {
		status = http.StatusInternalServerError
	}
	if sequenceNumber < 0 {
		sequenceNumber = 0
	}

	message := strings.TrimSpace(errText)
	if message == "" {
		message = http.StatusText(status)
	}

	code := openAIResponsesStreamErrorCode(status)

	trimmed := strings.TrimSpace(errText)
	if trimmed != "" && json.Valid([]byte(trimmed)) {
		var payload map[string]any
		if errUnmarshal := unmarshalJSONWithNumber([]byte(trimmed), &payload); errUnmarshal == nil {
			if v, ok := payload["sequence_number"]; ok {
				switch n := v.(type) {
				case json.Number:
					if seqInt, err := n.Int64(); err == nil {
						sequenceNumber = int(seqInt)
					}
				case float64:
					sequenceNumber = int(n)
				}
			}
		}
	}

	if strings.TrimSpace(code) == "" {
		code = "unknown_error"
	}

	errorDetail := openAIResponsesStreamErrorDetail(status, errText, code, message)

	data, errMarshal := json.Marshal(openAIResponsesStreamErrorChunk{
		Type:           "error",
		Error:          errorDetail,
		SequenceNumber: sequenceNumber,
	})
	if errMarshal == nil {
		return data
	}

	// Extremely defensive fallback.
	fallbackDetail := map[string]any{
		"type":    "server_error",
		"code":    "internal_server_error",
		"message": message,
		"param":   nil,
	}
	data, _ = json.Marshal(openAIResponsesStreamErrorChunk{
		Type:           "error",
		Error:          fallbackDetail,
		SequenceNumber: sequenceNumber,
	})
	if len(data) > 0 {
		return data
	}
	return []byte(`{"type":"error","error":{"type":"server_error","code":"internal_server_error","message":"internal error","param":null},"sequence_number":0}`)
}

func openAIResponsesStreamErrorDetail(status int, errText, code, message string) map[string]any {
	var payload map[string]any
	trimmed := strings.TrimSpace(errText)
	if trimmed != "" && json.Valid([]byte(trimmed)) {
		if errUnmarshal := unmarshalJSONWithNumber([]byte(trimmed), &payload); errUnmarshal == nil {
			if errorDetail, ok := payload["error"].(map[string]any); ok {
				return errorDetail
			}
			if response, ok := payload["response"].(map[string]any); ok {
				if errorDetail, ok := response["error"].(map[string]any); ok {
					return errorDetail
				}
			}
			if m, ok := payload["message"].(string); ok && strings.TrimSpace(m) != "" {
				message = strings.TrimSpace(m)
			}
			if v, ok := payload["code"]; ok && v != nil {
				if c, ok := v.(string); ok && strings.TrimSpace(c) != "" {
					code = strings.TrimSpace(c)
				} else {
					code = strings.TrimSpace(fmt.Sprint(v))
				}
			}
		}
	}

	errorType := openAIResponsesStreamErrorType(status)
	detail := map[string]any{
		"type":    errorType,
		"code":    code,
		"message": message,
		"param":   nil,
	}
	if payload != nil {
		if t, ok := payload["type"].(string); ok && strings.TrimSpace(t) != "" && strings.TrimSpace(t) != "error" {
			detail["type"] = strings.TrimSpace(t)
		}
		if paramVal, exists := payload["param"]; exists {
			detail["param"] = paramVal
		}
	}
	return detail
}

func openAIResponsesStreamFailedErrorDetail(status int, errText, code, message string) map[string]any {
	return openAIResponsesStreamErrorDetail(status, errText, code, message)
}

// BuildOpenAIResponsesStreamFailedChunk builds the terminal Responses event used by official Codex clients.
// It is intentionally separate from BuildOpenAIResponsesStreamErrorChunk so existing clients keep the legacy shape.
func BuildOpenAIResponsesStreamFailedChunk(status int, errText string, sequenceNumber int) []byte {
	if status <= 0 {
		status = http.StatusInternalServerError
	}
	if sequenceNumber < 0 {
		sequenceNumber = 0
	}

	errorChunkBytes := BuildOpenAIResponsesStreamErrorChunk(status, errText, sequenceNumber)
	var errorChunk openAIResponsesStreamErrorChunk
	_ = unmarshalJSONWithNumber(errorChunkBytes, &errorChunk)
	sequenceNumber = errorChunk.SequenceNumber

	errorDetail := errorChunk.Error
	if errorDetail == nil {
		code := openAIResponsesStreamErrorCode(status)
		message := strings.TrimSpace(errText)
		if message == "" {
			message = http.StatusText(status)
		}
		errorDetail = openAIResponsesStreamErrorDetail(status, errText, code, message)
	}

	data, errMarshal := json.Marshal(openAIResponsesStreamFailedChunk{
		Type:           "response.failed",
		SequenceNumber: sequenceNumber,
		Response: openAIResponsesStreamFailedResponse{
			Status: "failed",
			Error:  errorDetail,
		},
	})
	if errMarshal == nil {
		return data
	}

	return []byte(`{"type":"response.failed","sequence_number":0,"response":{"status":"failed","error":{"type":"server_error","code":"internal_server_error","message":"internal error"}}}`)
}

import json
import time

from modules import shared


def convert_request(body: dict) -> dict:
    """Transform Anthropic Messages API body into the dict that chat_completions_common expects."""
    messages = []

    # System message
    system = body.get('system')
    if system:
        if isinstance(system, list):
            # List of content blocks like [{"type":"text","text":"..."}]
            text_parts = [block.get('text', '') for block in system if isinstance(block, dict) and block.get('type') == 'text']
            system_text = '\n'.join(text_parts)
        else:
            system_text = str(system)
        if system_text:
            messages.append({"role": "system", "content": system_text})

    # Convert messages
    for msg in body.get('messages', []):
        role = msg.get('role')
        content = msg.get('content')

        if isinstance(content, str):
            messages.append({"role": role, "content": content})
            continue

        if not isinstance(content, list):
            messages.append({"role": role, "content": str(content) if content else ""})
            continue

        if role == 'assistant':
            # Split into text content, tool_calls, and skip thinking blocks
            text_parts = []
            tool_calls = []
            for block in content:
                btype = block.get('type')
                if btype == 'text':
                    text_parts.append(block.get('text', ''))
                elif btype == 'tool_use':
                    tool_calls.append({
                        "id": block.get('id', ''),
                        "type": "function",
                        "function": {
                            "name": block.get('name', ''),
                            "arguments": json.dumps(block.get('input', {}))
                        }
                    })
                elif btype == 'thinking':
                    pass  # Strip thinking blocks

            assistant_msg = {"role": "assistant", "content": '\n'.join(text_parts) if text_parts else ""}
            if tool_calls:
                assistant_msg["tool_calls"] = tool_calls
            messages.append(assistant_msg)

        elif role == 'user':
            # Handle tool_result blocks and regular content
            regular_parts = []
            for block in content:
                btype = block.get('type')
                if btype == 'tool_result':
                    # Emit any accumulated regular content first
                    if regular_parts:
                        if len(regular_parts) == 1 and regular_parts[0].get('type') == 'text':
                            messages.append({"role": "user", "content": regular_parts[0]['text']})
                        else:
                            messages.append({"role": "user", "content": regular_parts})
                        regular_parts = []
                    # Convert tool_result to OpenAI tool message
                    tool_content = block.get('content', '')
                    if isinstance(tool_content, list):
                        tool_content = '\n'.join(
                            b.get('text', '') for b in tool_content
                            if isinstance(b, dict) and b.get('type') == 'text'
                        )
                    messages.append({
                        "role": "tool",
                        "tool_call_id": block.get('tool_use_id', ''),
                        "content": str(tool_content)
                    })
                elif btype == 'text':
                    regular_parts.append({"type": "text", "text": block.get('text', '')})
                elif btype == 'image':
                    source = block.get('source', {})
                    if source.get('type') == 'base64':
                        media_type = source.get('media_type', 'image/png')
                        data = source.get('data', '')
                        regular_parts.append({
                            "type": "image_url",
                            "image_url": {"url": f"data:{media_type};base64,{data}"}
                        })
                elif btype == 'thinking':
                    pass  # Strip thinking blocks

            if regular_parts:
                if len(regular_parts) == 1 and regular_parts[0].get('type') == 'text':
                    messages.append({"role": "user", "content": regular_parts[0]['text']})
                else:
                    messages.append({"role": "user", "content": regular_parts})
        else:
            messages.append({"role": role, "content": str(content)})

    # Start with all fields from the original body (includes GenerationOptions defaults)
    result = dict(body)

    # Remove Anthropic-specific fields that don't map directly
    for key in ('system', 'stop_sequences', 'tools', 'tool_choice', 'thinking', 'metadata'):
        result.pop(key, None)

    # Set converted fields
    result['messages'] = messages
    result['max_tokens'] = body.get('max_tokens', 4096)
    result['stream'] = body.get('stream', False)
    result['mode'] = 'instruct'

    # Ensure ChatCompletionRequestParams defaults are present
    result.setdefault('continue_', False)
    result.setdefault('instruction_template', None)
    result.setdefault('instruction_template_str', None)
    result.setdefault('character', None)
    result.setdefault('bot_name', None)
    result.setdefault('context', None)
    result.setdefault('greeting', None)
    result.setdefault('user_name', None)
    result.setdefault('user_bio', None)
    result.setdefault('chat_template_str', None)
    result.setdefault('chat_instruct_command', 'Continue the chat dialogue below. Write a single reply for the character "<|character|>".\n\n<|prompt|>')
    result.setdefault('frequency_penalty', None)
    result.setdefault('presence_penalty', None)
    result.setdefault('logit_bias', None)
    result.setdefault('logprobs', None)
    result.setdefault('top_logprobs', None)
    result.setdefault('n', 1)
    result.setdefault('model', None)
    result.setdefault('functions', None)
    result.setdefault('function_call', None)
    result.setdefault('stream_options', None)
    result.setdefault('user', None)
    result.setdefault('stop', None)
    result.setdefault('tool_choice', None)

    # Always request usage in streaming so the usage-only chunk triggers
    # the deferred message_delta/message_stop with accurate output_tokens
    if body.get('stream', False):
        result['stream_options'] = {'include_usage': True}

    # Map stop_sequences -> stop
    if body.get('stop_sequences'):
        result['stop'] = body['stop_sequences']

    # Tools
    if body.get('tools'):
        result['tools'] = [
            {
                "type": "function",
                "function": {
                    "name": t.get('name', ''),
                    "description": t.get('description', ''),
                    "parameters": t.get('input_schema', {"type": "object", "properties": {}})
                }
            }
            for t in body['tools']
        ]

    # Tool choice
    tc = body.get('tool_choice')
    if tc and isinstance(tc, dict):
        tc_type = tc.get('type')
        if tc_type == 'auto':
            result['tool_choice'] = 'auto'
        elif tc_type == 'any':
            result['tool_choice'] = 'required'
        elif tc_type == 'tool':
            result['tool_choice'] = {"type": "function", "function": {"name": tc.get('name', '')}}
        elif tc_type == 'none':
            result['tool_choice'] = 'none'
    else:
        result.setdefault('tool_choice', None)

    # Thinking
    thinking = body.get('thinking')
    if thinking and isinstance(thinking, dict) and thinking.get('type') in ('enabled', 'adaptive'):
        result['enable_thinking'] = True

    return result


_FINISH_REASON_MAP = {
    "stop": "end_turn",
    "length": "max_tokens",
    "tool_calls": "tool_use",
}


def build_response(openai_resp: dict, model: str) -> dict:
    """Transform OpenAI chat completion response dict into Anthropic Messages format."""
    resp_id = openai_resp.get('id', 'msg_unknown')
    if resp_id.startswith('chatcmpl-'):
        resp_id = 'msg_' + resp_id[9:]

    choice = openai_resp.get('choices', [{}])[0]
    message = choice.get('message', {})

    content = []

    # Reasoning/thinking content
    reasoning = message.get('reasoning_content')
    if reasoning:
        content.append({"type": "thinking", "thinking": reasoning, "signature": ""})

    # Text content
    text = message.get('content')
    if text:
        content.append({"type": "text", "text": text})

    # Tool calls
    tool_calls = message.get('tool_calls')
    if tool_calls:
        for tc in tool_calls:
            func = tc.get('function', {})
            try:
                input_data = json.loads(func.get('arguments', '{}'))
            except (json.JSONDecodeError, TypeError):
                input_data = {}
            content.append({
                "type": "tool_use",
                "id": tc.get('id', ''),
                "name": func.get('name', ''),
                "input": input_data
            })

    finish_reason = choice.get('finish_reason', 'stop')
    stop_reason = _FINISH_REASON_MAP.get(finish_reason, 'end_turn')

    usage = openai_resp.get('usage', {})

    return {
        "id": resp_id,
        "type": "message",
        "role": "assistant",
        "content": content,
        "model": model,
        "stop_reason": stop_reason,
        "stop_sequence": None,
        "usage": {
            "input_tokens": usage.get('prompt_tokens', 0),
            "output_tokens": usage.get('completion_tokens', 0),
        }
    }


class StreamConverter:
    """Stateful converter: processes one OpenAI chunk at a time, yields Anthropic SSE events.

    When include_usage is enabled in the OpenAI request, the final chunk with
    finish_reason has usage=None, followed by a separate usage-only chunk
    (choices=[], usage={...}).  We defer emitting message_delta and message_stop
    until we receive that usage chunk so output_tokens is accurate.
    """

    def __init__(self, model: str):
        self.model = model
        self.msg_id = "msg_%d" % int(time.time() * 1000000000)
        self.block_index = 0
        self.in_thinking = False
        self.in_text = False
        self.input_tokens = 0
        self.output_tokens = 0
        self.tool_calls_accum = {}
        self.stop_reason = "end_turn"
        self._pending_finish = False  # True after we've seen finish_reason

    def process_chunk(self, chunk: dict) -> list[dict]:
        """Process a single OpenAI streaming chunk; return list of Anthropic SSE event dicts."""
        events = []
        choices = chunk.get('choices', [])
        usage = chunk.get('usage')

        if usage:
            self.input_tokens = usage.get('prompt_tokens', self.input_tokens)
            self.output_tokens = usage.get('completion_tokens', self.output_tokens)

        # Usage-only chunk (choices=[]) arrives after the finish chunk
        if not choices:
            if self._pending_finish:
                events.extend(self.finish())
            return events

        choice = choices[0]
        delta = choice.get('delta', {})
        finish_reason = choice.get('finish_reason')

        # First chunk with role
        if 'role' in delta:
            events.append({
                "event": "message_start",
                "data": json.dumps({
                    "type": "message_start",
                    "message": {
                        "id": self.msg_id,
                        "type": "message",
                        "role": "assistant",
                        "content": [],
                        "model": self.model,
                        "stop_reason": None,
                        "stop_sequence": None,
                        "usage": {"input_tokens": self.input_tokens, "output_tokens": 0}
                    }
                })
            })
            events.append({"event": "ping", "data": json.dumps({"type": "ping"})})
            return events

        # Reasoning content
        reasoning_content = delta.get('reasoning_content')
        if reasoning_content:
            if not self.in_thinking:
                self.in_thinking = True
                events.append({
                    "event": "content_block_start",
                    "data": json.dumps({
                        "type": "content_block_start",
                        "index": self.block_index,
                        "content_block": {"type": "thinking", "thinking": "", "signature": ""}
                    })
                })
            events.append({
                "event": "content_block_delta",
                "data": json.dumps({
                    "type": "content_block_delta",
                    "index": self.block_index,
                    "delta": {"type": "thinking_delta", "thinking": reasoning_content}
                })
            })
            return events

        # Text content
        text_content = delta.get('content')
        if text_content:
            if self.in_thinking:
                events.append({
                    "event": "content_block_stop",
                    "data": json.dumps({"type": "content_block_stop", "index": self.block_index})
                })
                self.in_thinking = False
                self.block_index += 1

            if not self.in_text:
                self.in_text = True
                events.append({
                    "event": "content_block_start",
                    "data": json.dumps({
                        "type": "content_block_start",
                        "index": self.block_index,
                        "content_block": {"type": "text", "text": ""}
                    })
                })
            events.append({
                "event": "content_block_delta",
                "data": json.dumps({
                    "type": "content_block_delta",
                    "index": self.block_index,
                    "delta": {"type": "text_delta", "text": text_content}
                })
            })
            return events

        # Tool calls in delta
        chunk_tool_calls = delta.get('tool_calls')
        if chunk_tool_calls:
            for tc in chunk_tool_calls:
                tc_id = tc.get('id', '')
                tc_idx = tc.get('index', 0)
                func = tc.get('function', {})
                if tc_id:
                    self.tool_calls_accum[tc_idx] = {
                        "id": tc_id,
                        "name": func.get('name', ''),
                        "arguments": func.get('arguments', '')
                    }
                elif tc_idx in self.tool_calls_accum:
                    self.tool_calls_accum[tc_idx]["arguments"] += func.get('arguments', '')

        # Final chunk — close open content blocks, defer message_delta/stop for usage
        if finish_reason is not None:
            self.stop_reason = _FINISH_REASON_MAP.get(finish_reason, 'end_turn')

            if self.in_thinking:
                events.append({
                    "event": "content_block_stop",
                    "data": json.dumps({"type": "content_block_stop", "index": self.block_index})
                })
                self.in_thinking = False
                self.block_index += 1

            if self.in_text:
                events.append({
                    "event": "content_block_stop",
                    "data": json.dumps({"type": "content_block_stop", "index": self.block_index})
                })
                self.in_text = False
                self.block_index += 1

            for tc_idx in sorted(self.tool_calls_accum.keys()):
                tc = self.tool_calls_accum[tc_idx]
                arguments_str = tc["arguments"] or "{}"

                events.append({
                    "event": "content_block_start",
                    "data": json.dumps({
                        "type": "content_block_start",
                        "index": self.block_index,
                        "content_block": {
                            "type": "tool_use",
                            "id": tc["id"],
                            "name": tc["name"],
                            "input": {}
                        }
                    })
                })
                # Emit the full input as a single input_json_delta so SDK
                # clients that reconstruct from deltas get the correct data
                events.append({
                    "event": "content_block_delta",
                    "data": json.dumps({
                        "type": "content_block_delta",
                        "index": self.block_index,
                        "delta": {
                            "type": "input_json_delta",
                            "partial_json": arguments_str
                        }
                    })
                })
                events.append({
                    "event": "content_block_stop",
                    "data": json.dumps({"type": "content_block_stop", "index": self.block_index})
                })
                self.block_index += 1

            # Defer message_delta/stop — usage chunk may follow
            self._pending_finish = True

        return events

    def finish(self) -> list[dict]:
        """Emit deferred message_delta and message_stop. Safe to call multiple times."""
        if not self._pending_finish:
            return []
        self._pending_finish = False
        return [
            {
                "event": "message_delta",
                "data": json.dumps({
                    "type": "message_delta",
                    "delta": {"stop_reason": self.stop_reason, "stop_sequence": None},
                    "usage": {"input_tokens": self.input_tokens, "output_tokens": self.output_tokens}
                })
            },
            {
                "event": "message_stop",
                "data": json.dumps({"type": "message_stop"})
            }
        ]

